def check_pairs():
    # Define the pairs and their conditions
    pairs = [
        {'x': 99, 'y': 10, 'valid': False},
        {'x': 85, 'y': 9, 'valid': True},
        {'x': 50, 'y': 7, 'valid': True},
        {'x': 1, 'y': 1, 'valid': True},
        {'x': 1, 'y': 0, 'valid': True}
    ]

    # Check each pair
    for pair in pairs:
        x = pair['x']
        y = pair['y']
        if y > (x ** 0.5):
            pair['valid'] = False
        else:
            pair['valid'] = True

    # Find the invalid pair
    for i, pair in enumerate(pairs):
        if not pair['valid']:
            # Return the corresponding choice (A is 0, B is 1, etc.)
            return chr(65 + i)

    return None

answer = check_pairs()
