def sharpeners():
    # Define the total number of sharpeners and total cost
    total_sharpeners = 18
    total_cost = 100

    # Iterate through possible numbers of white sharpeners (w)
    for w in range(1, total_sharpeners):
        b = total_sharpeners - w  # Calculate brown sharpeners
        # Calculate the price of brown sharpener (p)
        # Total cost equation: w*(p + 1) + b*p = 100
        # Simplifies to p = (100 - w) / 18
        p = (100 - w) / 18
        # Check if p is an integer (since price should be a whole number)
        if p.is_integer():
            # Check if the total cost matches
            if w * (p + 1) + b * p == total_cost:
                # Check which option matches (w, b)
                if (w, b) == (10, 8):
                    return 'A'
                elif (w, b) == (9, 8):
                    return 'B'
                elif (w, b) == (7, 8):
                    return 'C'
                elif (w, b) == (5, 6):
                    return 'D'
                elif (w, b) == (11, 12):
                    return 'E'
    return 'A'  # Default to A if no other option matches (though A should match)

answer = sharpeners()
